// Helper function to count the number of ones in the binary representation of an integer
function countOnes(x: int): int
    requires x >= 0
    ensures countOnes(x) >= 0
{
    var count := 0;
    var num := x;
    while num > 0
        decreases num
    {
        if num % 2 == 1 {
            count := count + 1;
        }
        num := num / 2;
    }
    return count;
}
